"use client";

import { HeroMedia, type HeroMediaData } from "./hero-media";
import { HeroContent } from "./hero-content";
import { useTheme } from "@/providers";
import type { ReactNode } from "react";

export type HeroData = {
  companyName: string;
  slogan: string;
  media?: HeroMediaData | null;
};

type HeroProps = {
  data: HeroData;
  children: ReactNode;
};

export function Hero({ data, children }: HeroProps) {
  const { tokens } = useTheme();

  return (
    <section
      className="relative w-full"
      aria-label="Hero"
    >
      {/* 
        Scroll animation area.

        200vh gives us enough scroll distance
        for the hero animation.
      */}
      <div className="relative">
        {/* =====================================================
            STICKY HERO
            ===================================================== */}

        <div className="sticky top-0 z-10 h-[75vh] w-full overflow-hidden">
          {/* Hero background */}
          <div className="hero-background absolute inset-0 origin-center">
            <HeroMedia media={data.media ?? null} />
          </div>

          {/* Overlay */}
          <div className="hero-overlay pointer-events-none absolute inset-0 bg-gradient-to-t from-black/60 via-black/30 to-black/10" />

          {/* Hero content */}
          <div className="hero-content absolute inset-0 flex items-center justify-start">
            <HeroContent
              companyName={data.companyName}
              slogan={data.slogan}
            />
          </div>
        </div>

        {/* =====================================================
            CONTENT THAT SLIDES OVER HERO
            ===================================================== */}

        <div className="hero-next-section absolute inset-x-0 top-0 z-20">
          {children}
        </div>
      </div>
    </section>
  );
}